'use strict';
const styles={editorial:{name:'白昼编辑室',en:'THE OBSERVATION DESK',desc:'把脉络展开，把判断留给证据。'},transit:{name:'轨道信号站',en:'SIGNAL TRANSIT',desc:'沿平台轨道，追踪同一议题的不同切面。'},console:{name:'夜航控制台',en:'NIGHTWATCH / RESEARCH TERMINAL',desc:'逐条检索，逐项核验。'},atlas:{name:'纸片研究所',en:'FIELD NOTES ATLAS',desc:'把观点放在一起，把差异看得更近。'}};
const platforms={bilibili:{name:'Bilibili',short:'B站',code:'BL',color:'#62a8b9',note:'创作流程与教程演示；少量简介索引，大部分近期线索来自二手汇总。'},xiaohongshu:{name:'小红书',short:'小红书',code:'RED',color:'#d57575',note:'工具的日常使用成本与可信度；原帖读取受限，以二手线索为主。'},weibo:{name:'微博',short:'微博',code:'WB',color:'#ce943a',note:'科技分类官方榜选取12条，另有职业转型与AI面试讨论；分类名次不等于综合榜。'},douyin:{name:'抖音',short:'抖音',code:'DY',color:'#766ec0',note:'10月4日22:41官方榜前10条，另有创作与历史访谈线索；热度不是人数。'},x:{name:'X',short:'X',code:'X',color:'#5b8390',note:'研究立场、开放模型与开发工具；当期帖子主要经公开二手转录。'},wechat:{name:'微信公众号',short:'公众号',code:'WX',color:'#689d76',note:'长文论证与业务应用；通过署名转载读取，未直接读取公众号原文。'}};
const sourceNames={official_rank:'官方榜单快照',secondary_report:'二手报道',search_snippet:'搜索索引',primary_post:'原始声明'};
const style=document.body.dataset.style,platform=document.body.dataset.platform,config=styles[style],isSummary=platform==='summary';
const qs=new URLSearchParams(location.search);let data=[],selected=new Set(),filtered=[],groups=[];
let state={q:qs.get('q')||'',domain:qs.get('domain')||'all',source:qs.get('source')||'all',time:qs.get('time')||'all'};
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=r=>r.published_at?String(r.published_at).slice(0,10):'日期未核验';
const old=r=>!!r.published_at&&String(r.published_at).slice(0,10)<'2026-10-01';
const displayAuthor=r=>r.account_name||r.author_name||r.author||'发布者未核验';
const sourceURL=r=>r.evidence_url||r.secondary_source_url||r.source_url||r.url;
const tags=r=>`<span class="badge platform-badge">${platforms[r.platform]?.short||e(r.platform)}</span><span class="badge ${r.source_type}">${sourceNames[r.source_type]||e(r.source_type)}</span>${r.background?'<span class="badge warn">官网背景 · 非X帖</span>':r.excluded_from_metrics?'<span class="badge warn">弱线索 · 不计覆盖</span>':old(r)?'<span class="badge warn">历史材料</span>':''}`;
const counts=rs=>Object.keys(platforms).map(p=>({p,n:rs.filter(r=>r.platform===p&&!r.excluded_from_metrics).length}));
function route(p,s=style){return `/${s}/${p}/`;}
function shell(){let nav=Object.entries(platforms).map(([p,v])=>`<a href="${route(p)}" ${p===platform?'aria-current="page"':''}><i style="--p:${v.color}">${v.code}</i><span>${v.name}</span></a>`).join('');document.getElementById('app').innerHTML=`<header class="topbar"><a class="brand" href="/"><img src="/favicon.svg" alt="">澄镜 <span>${config.en}</span></a><div class="top-tools"><span class="stamp">2026.10.04 · 公开样本</span><label class="style-switch"><span class="sr">切换工作台</span><select id="style-select">${Object.entries(styles).map(([k,v])=>`<option value="${k}" ${k===style?'selected':''}>${v.name}</option>`).join('')}</select></label><a class="hub-link" href="/">视图总览 ↗</a></div></header><div class="workspace"><nav class="platform-nav" aria-label="平台导航"><a class="summary-link" href="${route('summary')}" ${isSummary?'aria-current="page"':''}><i>◎</i><span>跨平台综述</span></a>${nav}<div class="nav-bottom">PUBLIC EVIDENCE<br>有出处，才有讨论。</div></nav><main id="main"><section class="page-heading"><div><p class="eyebrow">${isSummary?'CROSS-PLATFORM / OVERVIEW':`${platforms[platform].code} / PLATFORM FIELD NOTES`}</p><h1>${isSummary?'同一个世界，不同的讨论切面':platforms[platform].name+' 观察页'}</h1><p>${isSummary?config.desc:platforms[platform].note}</p></div><span class="page-mark">${isSummary?'06':platforms[platform].code}<small>${isSummary?'PLATFORMS':'SOURCE'}</small></span></section><div class="boundary"><span class="boundary-icon">ⓘ</span><p><strong>公开样本 + 微博、抖音官方榜单快照。</strong> 另四个平台官方榜未核验。索引、转载、原始材料分开标记；条目数只表示覆盖，热度值不等于人数。无可审计分母，不显示观点占比。</p><button data-action="method">方法与缺口 ↗</button></div><form class="filters" id="filters"><label class="search"><span>⌕</span><input id="search" type="search" placeholder="检索议题、作者或观点…" aria-label="关键词" value="${e(state.q)}"><kbd>/</kbd></label><label><span class="sr">领域</span><select id="domain"><option value="all">所有领域</option><option value="AI">AI 与技术应用</option><option value="other">其他公共讨论</option><optgroup label="细分领域">${[...new Set(data.filter(r=>isSummary||r.platform===platform).map(r=>r.domain))].sort().map(domain=>`<option value="domain:${e(domain)}">${e(domain)}</option>`).join('')}</optgroup></select></label><label><span class="sr">证据类型</span><select id="source"><option value="all">所有证据</option><option value="official_rank">官方榜单快照</option><option value="secondary_report">二手报道</option><option value="search_snippet">搜索索引</option><option value="primary_post">原始声明 / 背景</option></select></label><label><span class="sr">时间范围</span><select id="time"><option value="all">全部时间（含历史）</option><option value="recent">10月1日后有日期</option><option value="unknown">日期未核验</option></select></label><button type="button" data-action="reset" class="text-button">重置</button><div class="export-tools"><button type="button" data-export="json">JSON ↓</button><button type="button" data-export="csv">CSV ↓</button></div></form><div class="result-line"><span id="result-count" aria-live="polite"></span><span class="muted">证据编号是索引，不是排名</span></div><div id="content"></div><footer class="workspace-footer"><span>澄镜 / ${config.name}</span><span>静态研究快照 · 采集时间见每条证据 · 无自动更新</span><button data-action="method">采样说明</button></footer></main></div><div id="selection-bar" class="selection-bar" hidden><span id="selected-count"></span><button data-action="compare">并排比较 →</button><button data-action="clear" aria-label="清空比较">清空</button></div>`;for(const k of ['domain','source','time'])document.getElementById(k).value=state[k];
 document.getElementById('style-select').onchange=ev=>location.href=route(platform,ev.target.value)+location.search;
 document.getElementById('filters').onsubmit=ev=>ev.preventDefault();document.getElementById('search').oninput=ev=>{state.q=ev.target.value;render();};for(const k of ['domain','source','time'])document.getElementById(k).onchange=ev=>{state[k]=ev.target.value;render();};}
function applies(r){return (isSummary||r.platform===platform)&&(!state.q||[r.title,r.topic,r.claim,r.stance_summary,displayAuthor(r),r.id].join(' ').toLowerCase().includes(state.q.toLowerCase()))&&(state.domain==='all'||(state.domain==='AI'?(r.domain||'').includes('AI'):state.domain==='other'?!(r.domain||'').includes('AI'):state.domain==='domain:'+r.domain))&&(state.source==='all'||r.source_type===state.source)&&(state.time==='all'||(state.time==='unknown'?!r.published_at:!!r.published_at&&date(r)>='2026-10-01'));}
function record(r,index=0){return `<article class="record ${r.background?'background-record':''}" data-id="${r.id}"><div class="record-kicker"><span>${e(r.id)} / ${e(r.domain)}</span><label class="compare-check"><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="比较 ${e(r.title)}"><span>比较</span></label></div><div class="record-badges">${tags(r)}</div><h3><button data-evidence="${r.id}">${e(r.title)}</button></h3><p class="record-claim">${e(r.claim)}</p><div class="stance"><span>观点线索</span><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p></div><div class="record-meta"><span>${e(displayAuthor(r))}</span><time>${e(date(r))}</time></div><div class="record-actions"><button data-evidence="${r.id}">查看证据 <span>↗</span></button><a href="${e(sourceURL(r))}" target="_blank" rel="noopener noreferrer">${r.source_type==='secondary_report'?'读二手来源':'打开来源'} ↗</a></div></article>`;}
function rows(rs){return `<div class="table-scroll"><table class="evidence-table"><thead><tr><th>选择</th><th>索引 / 平台</th><th>议题与观点</th><th>证据层级</th><th>发布日</th><th>证据</th></tr></thead><tbody>${rs.map(r=>`<tr><td><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="比较 ${e(r.title)}"></td><td><b>${e(r.id)}</b><small>${platforms[r.platform].name}</small></td><td><button class="table-title" data-evidence="${r.id}">${e(r.title)}</button><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p></td><td><span class="badge ${r.source_type}">${sourceNames[r.source_type]}</span>${r.background?'<small>非 X 帖 · 背景</small>':old(r)?'<small>历史材料</small>':''}</td><td>${e(date(r))}</td><td><button data-evidence="${r.id}" class="evidence-link" aria-label="打开 ${e(r.title)} 的证据">↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function coverage(rs){return `<section class="coverage-panel"><header class="section-head"><h2>采样覆盖</h2><span>仅计本轮条目</span></header><div class="coverage-bars">${counts(rs).map(({p,n})=>`<a href="${route(p)}"><span>${platforms[p].short}</span><div class="bar-track"><i style="width:${n/Math.max(1,...counts(rs).map(v=>v.n))*100}%;background:${platforms[p].color}"></i></div><b>${n}</b></a>`).join('')}</div><p class="fine">数量反映检索覆盖，不可用来比较平台热度。官网背景与未核验弱线索不计入平台覆盖。</p></section>`;}
function gap(){return `<section class="gap-panel"><span class="eyebrow">WHAT WE DO NOT KNOW</span><h2>留白也是信息</h2><div class="empty-chart"><span>—</span><p>观点占比不可用</p></div><p>未获得完整评论样本与一致分母。当前不生成支持率、反对率或受众画像。</p><dl><div><dt>官方热榜</dt><dd>微博、抖音有快照</dd></div><div><dt>原帖实时互动</dt><dd>多数不可用</dd></div><div><dt>人群比例</dt><dd>无证据</dd></div></dl></section>`;}
function story(g,i){const ids=g.ids||g.evidence_ids||[];const visible=ids.map(id=>filtered.find(r=>r.id===id)).filter(Boolean);if(!visible.length)return '';return `<article class="story"><div class="story-top"><span class="story-number">${String(i+1).padStart(2,'0')}</span><span class="badge">${e(g.kind||'同题对照')}</span><span>${new Set(visible.map(r=>r.platform)).size} 平台 · ${visible.length} 条可见证据</span></div><h2>${e(g.title)}</h2><p class="story-summary">${e(g.summary)}</p><div class="story-voices">${visible.map(r=>`<button data-evidence="${r.id}" class="voice"><span><i style="background:${platforms[r.platform].color}"></i>${platforms[r.platform].short} / ${r.id}</span><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p><small>${e(date(r))} · ${sourceNames[r.source_type]} ↗</small></button>`).join('')}</div><p class="story-caution">${e(g.caution||'这些是具体作者或标题的表达，不代表整个平台。')}</p><button class="text-button" data-group="${i}">选择这些证据进行比较 →</button></article>`;}
function summary(){const stories=groups.map(story).join('');if(style==='editorial')return `<div class="editorial-layout"><section class="main-stories"><div class="section-head"><h2>议题对照 / THE BRIEF</h2><span>按论证组织，不按热度排序</span></div>${stories||empty()}</section><aside>${coverage(filtered)}${gap()}<div class="margin-note"><b>时间核验</b><p>“两类劳动”至少在 6 月已有同题材材料。10 月出现的是再次传播，不等于首次发言。</p><button data-evidence="WD10">查看历史线索 ↗</button></div></aside></div><section class="all-records"><div class="section-head"><h2>证据档案</h2><span>筛选后的全部条目</span></div><div class="records-grid">${filtered.map(record).join('')}</div></section>`;
if(style==='transit')return `${coverage(filtered)}<section class="platform-lanes">${Object.entries(platforms).map(([p,v])=>{let rs=filtered.filter(r=>r.platform===p);return `<section class="lane" style="--lane:${v.color}"><header><i>${v.code}</i><h2>${v.name}</h2><span>${rs.filter(r=>!r.excluded_from_metrics).length} 条</span><a href="${route(p)}" aria-label="进入${v.name}">↗</a></header><div class="lane-records">${rs.length?rs.map(record).join(''):'<p class="empty-inline">此筛选下没有条目</p>'}</div></section>`}).join('')}</section><div class="section-head"><h2>换乘：同题证据</h2></div><section class="story-grid">${stories}</section>`;
if(style==='console')return `<div class="console-strip"><div><span>VISIBLE RECORDS</span><b>${filtered.length}</b></div><div><span>PLATFORMS OBSERVED</span><b>${new Set(filtered.map(r=>r.platform)).size}/6</b></div><div><span>OPINION SHARE</span><b>N/A</b></div><div><span>OFFICIAL SNAPSHOTS</span><b>2/6</b></div></div><div class="console-layout"><section><div class="section-head"><h2>证据流 / EVIDENCE LOG</h2><span>点选标题展开来源</span></div>${rows(filtered)}</section><aside>${gap()}<section class="console-brief"><h2>同题综述</h2>${groups.map((g,i)=>`<details><summary><b>${String(i+1).padStart(2,'0')}</b> ${e(g.title)}</summary><p>${e(g.summary)}</p><small>${e(g.caution)}</small><button data-group="${i}">比较相关证据 ↗</button></details>`).join('')}</section></aside></div>`;
return `<div class="atlas-overview">${coverage(filtered)}<div class="atlas-note"><p class="eyebrow">RESEARCH NOTE / 04 OCT</p><h2>同题不一定对立，<br>差异值得细读。</h2><p>先区分“关注重点不同”和“彼此矛盾”。同一转载链也不是独立验证。</p><span>✧</span></div></div><section class="story-grid">${stories}</section><div class="section-head"><h2>所有证据卡</h2><span>可勾选并排比较</span></div><div class="atlas-records">${filtered.map(record).join('')}</div>`;}
function platformView(){let rs=filtered;const active=rs.filter(r=>!r.excluded_from_metrics);const info=`<section class="platform-brief"><div><span>本页可见样本</span><b>${active.length}<small>条</small></b></div><div><span>有日期的材料</span><b>${active.filter(r=>r.published_at).length}<small>条</small></b></div><div><span>可核验人群占比</span><b>—<small>不可用</small></b></div><p>${platforms[platform].note}</p></section>`;if(!rs.length)return info+empty();if(style==='console')return info+`<div class="console-layout"><section>${rows(rs)}</section><aside>${gap()}</aside></div>`;if(style==='transit'){const categories=[['近期线索',rs.filter(r=>!old(r)&&r.published_at)],['历史参照',rs.filter(old)],['日期待核验',rs.filter(r=>!r.published_at)]];return info+`<div class="time-lanes">${categories.map(([name,records])=>`<section class="lane" style="--lane:${platforms[platform].color}"><header><i>●</i><h2>${name}</h2><span>${records.length} 条</span></header><div class="lane-records">${records.map(record).join('')||'<p class="empty-inline">当前没有可用条目</p>'}</div></section>`).join('')}</div>`;}if(style==='atlas')return info+`<div class="atlas-records">${rs.map(record).join('')}</div>`;return info+`<div class="editorial-layout"><section class="records-grid">${rs.map(record).join('')}</section><aside>${gap()}<section class="margin-note"><b>阅读顺序</b><p>标题是入口。观点摘要注明作者表达；证据抽屉保留原始日期、来源关系、互动口径与缺口。</p></section></aside></div>`;}
function empty(){return '<section class="empty"><span>⌕</span><h2>没有匹配的证据</h2><p>尝试更短的关键词，或放宽时间与证据类型。</p><button data-action="reset">清除筛选</button></section>';}
function officialPanel(){return ['weibo','douyin'].map(p=>{const rs=filtered.filter(r=>r.source_type==='official_rank'&&r.platform===p);if(!rs.length)return '';const wb=p==='weibo';return `<details class="official-panel" ${!isSummary?'open':''}><summary><div><p class="eyebrow">VERIFIED SNAPSHOT / ${wb?'WEIBO TECH':'DOUYIN'}</p><h2>${wb?'微博科技分类榜 · 选取12项':'抖音官方热榜 · 已保存前10项'}</h2></div><span>2026.10.04 ${wb?'22:44:52':'22:41:58'} · UTC+8 <b>⌄</b></span></summary><p>${wb?'科技分类榜观察到30项，按AI/硬件主题选取12项；名次不是综合榜排名，不能用所选条目推算全榜占比。':'单次读取；前10条未出现明确AI议题，不代表平台没有AI讨论。'} 热度不是播放量、评论量或人数。当前筛选可见${rs.length}条。</p><div class="official-ranks">${rs.map(r=>`<button data-evidence="${r.id}"><b>${r.observed_metrics.rank??r.observed_metrics.category_rank}</b><span>${e(r.title)}</span><small>${e(r.observed_metrics.heat_display??r.observed_metrics.displayed_heat+' 热度')}</small></button>`).join('')}</div></details>`;}).join('');}
function render(){filtered=data.filter(applies);const nonBg=filtered.filter(r=>!r.excluded_from_metrics).length;document.getElementById('result-count').textContent=`${nonBg} 条可见平台线索${filtered.length>nonBg?' + '+(filtered.length-nonBg)+' 条背景 / 待核验线索':''} / ${data.filter(r=>(isSummary||r.platform===platform)&&!r.excluded_from_metrics).length} 条已收录平台线索`;document.getElementById('content').innerHTML=officialPanel()+(isSummary?summary():platformView());const query=new URLSearchParams();for(const [k,v]of Object.entries(state))if(v&&v!=='all')query.set(k,v);history.replaceState(null,'',location.pathname+(query.size?'?'+query:''));updateSelection();}
function updateSelection(){document.getElementById('selection-bar').hidden=!selected.size;document.getElementById('selected-count').textContent=`已选 ${selected.size} 条证据`;document.querySelectorAll('[data-select]').forEach(input=>input.checked=selected.has(input.dataset.select));}
function showDialog(id,html){let d=document.getElementById(id);d.innerHTML=`<div class="dialog-heading"><span>${id==='evidence'?'EVIDENCE / 证据档案':'SIDE BY SIDE / 并排比较'}</span><button class="close" data-close="${id}" aria-label="关闭">×</button></div>${html}`;d.showModal();}
function evidence(id){const r=data.find(r=>r.id===id);if(!r)return;let metrics=r.observed_metrics?Object.entries(r.observed_metrics).map(([k,v])=>`<div><dt>${e(metricLabel(k))}</dt><dd>${e(Array.isArray(v)?v.join(' / '):typeof v==='object'?JSON.stringify(v):v)}</dd></div>`).join(''):'<div><dt>互动数据</dt><dd>未获取；不补零、不推算</dd></div>';let role=r.author_profile?.role||r.author_role||'未获取可核验的作者身份自述';showDialog('evidence',`<div class="dialog-body"><div class="record-badges">${tags(r)}<span class="badge">${e(r.id)}</span></div><h2>${e(r.title)}</h2><p class="lead">${e(r.claim)}</p><section><h3>可支持的观点</h3><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p></section><section><h3>发布者与身份依据</h3><p>${e(displayAuthor(r))}</p><p>${e(role)}</p>${r.author_profile?.basis?`<p class="fine">依据：${e(r.author_profile.basis)}</p>`:''}<p class="fine">只记录公开自述或机构角色，不据此推断受众属性。</p></section><dl class="evidence-facts"><div><dt>材料发布日期</dt><dd>${e(r.published_at||'未核验')}</dd></div><div><dt>原始公众号日期</dt><dd>${e(r.original_published_at||'未获取 / 不适用')}</dd></div><div><dt>事件日期</dt><dd>${e(r.event_dates||'未单独核验')}</dd></div><div><dt>采集时间</dt><dd>${e(r.captured_at)}</dd></div>${r.source_relationship?`<div><dt>转载关系</dt><dd>${e(r.source_relationship)}</dd></div>`:''}</dl><section><h3>来源的显示值</h3><p class="fine">保留原口径与时间。账号累计数据不是单帖互动；二手历史数值不是实时数值。</p><dl class="evidence-facts">${metrics}</dl></section><section class="limit-box"><h3>证据边界</h3><p>${e(Array.isArray(r.limitations)?r.limitations.join(' '):r.limitations)}</p>${r.id==='WD01'||r.id==='WD02'||r.id==='WD10'?'<p>6月28日已出现同题材视频。10月4日传播不能视为首次发言；完整访谈和原始事件时间仍待核验。</p>':''}</section><div class="dialog-links"><a class="primary-button" href="${e(sourceURL(r))}" target="_blank" rel="noopener noreferrer">打开已读取的来源 ↗</a>${sourceURL(r)!==r.url?`<a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">原帖链接（可能受限）↗</a>`:''}</div></div>`);}
function metricLabel(k){return ({rank:'榜单名次',category_rank:'科技分类名次',displayed_heat:'显示热度（非人数）',rank_scope:'排名范围',heat_display:'平台热度（非人数）',measurement:'指标定义',likes_display:'赞（显示值）',comments_display:'评论（显示值）',provenance:'数字来源',measurement_time:'测量时间',note:'口径备注',video_views_display:'视频观看（显示值）',account_followers_display:'账号粉丝（非单帖）',account_total_likes_display:'账号累计获赞（非单帖）',unlabelled_post_values:'无标签数值（不赋予指标）',want_to_go:'想去（显示值）',discussion_count_display:'活动讨论（显示值）'})[k]||k;}
function compare(){const rs=data.filter(r=>selected.has(r.id));if(!rs.length)return;showDialog('compare',`<div class="dialog-body"><h2>${rs.length} 条证据，逐项对照</h2><p class="fine">手动选择不会自动建立同题关系。先核对具体命题、发布时间及转载链，再判断是否存在分歧。</p><div class="compare-grid">${rs.map(r=>`<section><div class="record-badges">${tags(r)}</div><h3>${e(r.topic)}</h3><strong>${e(r.id)} · ${e(displayAuthor(r))}</strong><h4>材料日期</h4><p>${e(r.published_at||'未核验')}</p><h4>具体表达</h4><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p><h4>局限</h4><p class="fine">${e(Array.isArray(r.limitations)?r.limitations.join(' '):r.limitations)}</p><a href="${e(sourceURL(r))}" target="_blank" rel="noopener noreferrer">来源 ↗</a></section>`).join('')}</div><button class="primary-button" data-export="selected">导出已选证据 JSON ↓</button></div>`);}
function method(){showDialog('evidence',`<div class="dialog-body"><p class="eyebrow">RESEARCH BOUNDARIES</p><h2>我们看到了什么，<br>又没看到什么。</h2><p class="lead">2026年10月4日公开资料采样，聚焦 AI，辅以实际取到的文化、假日与其他议题。数据不是全量，也不代表平台总体。</p><section><h3>01 / 四种证据，分开阅读</h3><p>官方榜单仅核验采集时刻的排名与平台热度，不证明标题事件本身。搜索索引仅证明搜索服务当时展示了该摘要。二手报道保留原帖链接与转载关系。原始声明是可读取的机构材料；X03 是2025年官网背景，不计为当前 X 帖子。</p></section><section><h3>02 / 不能得到的数字，不画图</h3><p>抖音官方榜在10月4日22:41:58（UTC+8）直接可读，保存前10个排名项；另有置顶内容未计入排名。微博科技分类榜在22:44:52（UTC+8）读取30项，选取其中12条AI/硬件线索，分类名次不等于综合名次。微博话题点击会进入登录页，完整话题和评论未读取。另四个平台官方榜、统一时刻互动、代表性评论样本及受众画像尚未取得。页面覆盖图只展示收录条目数，不表示声量、流行程度、意见占比或用户结构。</p></section><section><h3>03 / 不同日期各司其职</h3><p>材料发布日期、事件日、采集时间分别记录。公众号日期通常属于转载页。李飞飞“两类劳动”的同题材6月已出现，10月是再次传播线索。缺失或矛盾日期保持可见。</p></section><section><h3>04 / 对照观点，不制造对立</h3><p>同题材料至少跨两个平台，才用作跨平台议题对照。不同关注重点不等于相反立场；转述同一原文不是独立验证。作者与受众严格分开，只记录公开自述角色。</p></section><section><h3>05 / 检索与导出范围</h3><p>筛选和导出均作用于当前页面的真实证据。JSON 保留完整口径，CSV 便于进一步研究。所有内容均为固定快照；无持续监控或自动刷新。</p></section></div>`);}
function exportData(type){const rs=type==='selected'?data.filter(r=>selected.has(r.id)):filtered;let content,mime,ext;if(type==='csv'){let fields=['id','platform','topic','domain','published_at','captured_at','source_type','claim','stance_summary','observed_metrics','author_name','account_name','url','source_url','evidence_url','secondary_source_url','excluded_from_metrics','limitations'];const c=v=>'"'+String(Array.isArray(v)?v.join(' '):v&&typeof v==='object'?JSON.stringify(v):v??'').replace(/"/g,'""')+'"';content='\ufeff'+[fields.map(c).join(','),...rs.map(r=>fields.map(k=>c(r[k])).join(','))].join('\r\n');mime='text/csv;charset=utf-8';ext='csv';}else{content=JSON.stringify({snapshot:'2026-10-04',scope:'公开讨论样本；非热榜、非代表性调查',filters:state,records:rs},null,2);mime='application/json';ext='json';}let url=URL.createObjectURL(new Blob([content],{type:mime}));let a=document.createElement('a');a.href=url;a.download=`chengjing-${platform}-${rs.length}-records.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`已导出 ${rs.length} 条证据`);}
function notify(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),2400);}
document.addEventListener('click',ev=>{const t=ev.target.closest('button,a');if(!t)return;if(t.dataset.evidence)evidence(t.dataset.evidence);if(t.dataset.close)document.getElementById(t.dataset.close).close();if(t.dataset.export)exportData(t.dataset.export);if(t.dataset.group!==undefined){let g=groups[+t.dataset.group];(g.ids||g.evidence_ids||[]).filter(id=>filtered.some(r=>r.id===id)).forEach(id=>selected.add(id));updateSelection();compare();}switch(t.dataset.action){case'method':method();break;case'compare':compare();break;case'clear':selected.clear();updateSelection();break;case'reset':state={q:'',domain:'all',source:'all',time:'all'};document.getElementById('search').value='';for(let k of ['domain','source','time'])document.getElementById(k).value='all';render();break;}});
document.addEventListener('change',ev=>{let id=ev.target.dataset.select;if(id){if(ev.target.checked)selected.add(id);else selected.delete(id);updateSelection();}});
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){ev.preventDefault();document.getElementById('search').focus();}});
for(let d of document.querySelectorAll('dialog'))d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close();}});
const fallbackGroups=[{title:'AI面试：初筛效率与沟通体验',kind:'同一场景 · 关注差异',summary:'微博作者谈拟人面试的不适、情绪劳动和初筛边界；公众号关联文章强调标准化效率与双向沟通。这里呈现互补关注，并非平台间阵营对立。',ids:['WD04','WD05','WD06','WX06']},{title:'AI输出：生成之后，谁来读懂？',kind:'同类问题 · 非相反立场',summary:'小红书标题指出阅读负担，公众号与 X 讨论约束写作和可视化。共同问题是输出可理解性；使用不同工具和任务，不能直接比较效果。',ids:['BX09','WX01','X08']},{title:'“两类劳动”：传播日期不是事件日期',kind:'同题材 · 历史对照',summary:'10月微博再传播与6月抖音视频出现类似主题。6月材料只能证明题材此前已出现，不能确定完整访谈的原始日期。',ids:['WD01','WD02','WD10'],caution:'历史标题采取反焦虑框架；当期作者自我定位不能代表劳动者总体。'}];
fetch('/data.json').then(r=>{if(!r.ok)throw Error('数据载入失败');return r.json();}).then(d=>{data=d.records;groups=Array.isArray(d.synthesis?.groups)?d.synthesis.groups.map(g=>({...g,kind:g.relation,summary:g.assessment,caution:(g.limitations||[]).join(' ')})):fallbackGroups;shell();render();}).catch(err=>{document.getElementById('app').innerHTML=`<main class="empty"><h1>证据暂时没有载入</h1><p>${e(err.message)}</p><button onclick="location.reload()">重试</button><a href="/">回到视图总览</a></main>`;});
